<?php

/* @autogenerated */
declare(strict_types=1);

namespace {
    use PHPUnit\Framework\TestCase;
    use PHPUnit\Framework\Attributes\AllowMockObjectsWithoutExpectations;
    use Slim\Routing\RouteCollectorProxy;
    use Civi\Lughauth\Bootstrap\Plugin\NotificationPlugin;
    use Civi\Lughauth\Shared\Infrastructure\AggregatedMicroPlugin;

    /**
     * Unit tests for {@see NotificationPlugin}.
     */
    #[AllowMockObjectsWithoutExpectations]
    final class NotificationPluginUnitTest extends TestCase
    {
        /**
         * Ensures NotificationPlugin is an AggregatedMicroPlugin.
         */
        public function testIsAggregatedMicroPlugin(): void
        {
            $plugin = new NotificationPlugin();

            $this->assertInstanceOf(AggregatedMicroPlugin::class, $plugin);
        }

        /**
         * Ensures route delegation reaches all child plugins.
         */
        public function testDelegatesRouteRegistration(): void
        {
            $plugin = new NotificationPlugin();
            $collector = $this->createMock(RouteCollectorProxy::class);

            $collector->expects($this->atLeastOnce())->method('group');

            $plugin->registerRoutes($collector);
        }

        /**
         * Ensures service definitions from all child plugins are aggregated.
         */
        public function testAggregatesServiceDefinitions(): void
        {
            $plugin = new NotificationPlugin();

            $result = $plugin->registerServiceDefinition([]);

            $this->assertNotEmpty($result);
        }
    }
}
